<?php require_once '../includes/auth.php';require_login();verify_csrf();$u=user();if(!isset($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)exit('Upload failed');$f=$_FILES['file'];if($f['size']>25*1024*1024)exit('Maximum file size is 25 MB.');$allowed=['pdf','doc','docx','txt','jpg','jpeg','png','xlsx','xls','csv','ppt','pptx','zip'];$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,$allowed,true))exit('File type not allowed');$stored=bin2hex(random_bytes(16)).'.'.$ext;$dir=__DIR__.'/../uploads';if(!is_dir($dir))mkdir($dir,0750,true);if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$stored))exit('Upload storage failed');$cat=in_array($ext,['jpg','jpeg','png'])?'image':(in_array($ext,['xlsx','xls','csv'])?'spreadsheet':(in_array($ext,['ppt','pptx'])?'presentation':(in_array($ext,['zip'])?'archive':'document')));$mime=mime_content_type($dir.'/'.$stored);$desc=trim($_POST['description']??'');$s=mysqli_prepare($conn,"INSERT INTO user_files(original_name,stored_name,mime_type,size,category,description,owner_id,institution_type,institution_code) VALUES(?,?,?,?,?,?,?,?,?)");mysqli_stmt_bind_param($s,'sssississ',$f['name'],$stored,$mime,$f['size'],$cat,$desc,$u['id'],$u['institution_type'],$u['institution_code']);mysqli_stmt_execute($s);log_activity('created','files',$f['name'],mysqli_insert_id($conn));flash('success','File uploaded.');redirect('list.php');
